mapper.select:
SELECT r.case_id,r.payment_id,r.reason,r.owner,r.status,r.last_checked_at,r.next_check_at,
  r.resolved_at,r.provider_summary
FROM biz_payment_review_case r JOIN biz_payment p ON p.id=r.payment_id AND NOT p.deleted
WHERE r.status='open'
AND r.case_id > #{after}
ORDER BY r.case_id LIMIT #{limit}

SELECT FROM biz_payment WHERE intent_id IS NOT NULL AND NOT deleted AND status='created' AND create_time < #{now} AND checkout_session_id IS NOT NULL AND (quote_valid_until <= #{now} OR business_deadline <= #{now}) AND NOT EXISTS(SELECT 1 FROM biz_payment_review_case r WHERE r.payment_id=biz_payment.id AND r.status='open')
AND (create_time,id) > (#{afterTime},#{afterId})
ORDER BY create_time,id LIMIT #{limit}
